func permute(_ nums: [Int]) -> [[Int]] {
    var a = nums, result: [[Int]] = []
    func backtrack(_ i: Int) {
        if i == a.count { result.append(a); return }
        for j in i..<a.count {
            a.swapAt(i, j); backtrack(i + 1); a.swapAt(i, j)
        }
    }
    backtrack(0)
    return result
}
